#!/usr/bin/env bash
# Навыки моушн-дизайна, которые Бато поставил в Claude Code (npx skills add). Источник списка: ~/.agents/.skill-lock.json.
# Клонирует их в /tmp/ds-skills (сеть GitHub в облаке открыта, npm — нет).
set -u; D=${1:-/tmp/ds-skills}; mkdir -p "$D"
[ -d "$D/CloudAI-X__threejs-skills" ] || git clone -q --depth 1 https://github.com/CloudAI-X/threejs-skills.git "$D/CloudAI-X__threejs-skills" || echo "fail CloudAI-X/threejs-skills"
[ -d "$D/Leonxlnx__taste-skill" ] || git clone -q --depth 1 https://github.com/Leonxlnx/taste-skill.git "$D/Leonxlnx__taste-skill" || echo "fail Leonxlnx/taste-skill"
